query GetPokemonTypes($where: pokemon_bool_exp!, $limit: Int!, $typeLimit: Int!) {
  pokemon(where: $where, order_by: {id: asc}, limit: $limit) {
    id
    name
    is_default
    pokemontypes(limit: $typeLimit, order_by: {slot: asc}) {
      slot
      type { id name }
    }
  }
}

query GetCharizardTypes($name: String!, $limit: Int!) {
  pokemon(where: {name: {_eq: $name}}, limit: $limit) {
    id
    name
    pokemontypes(order_by: {slot: asc}, limit: $limit) {
      slot
      type {
        id
        name
      }
    }
  }
}

query JohtoSteel($generationId: Int!, $typeName: String!, $isDefault: Boolean!, $limit: Int!) {
  pokemonspecies(
    where: {
      generation_id: {_eq: $generationId}
      pokemons: {
        is_default: {_eq: $isDefault}
        pokemontypes: {type: {name: {_eq: $typeName}}}
      }
    }
    order_by: {id: asc}
    limit: $limit
  ) {
    id
    name
    generation_id
    pokemons(limit: 1, where: {is_default: {_eq: $isDefault}}) {
      id
      name
      is_default
      pokemontypes(limit: 2) { type { name } }
    }
  }
}

query GetJohtoSteelPokemon($generationId: Int!, $typeName: String!, $limit: Int!) {
