query GetAbilitySturdy($name: String!, $lang: String!, $limit: Int!, $textLimit: Int!) {
  ability(where: {name: {_eq: $name}}, limit: $limit) {
    id
    name
    abilityeffecttexts(where: {language: {iso639: {_eq: $lang}}}, limit: $textLimit) {
      effect
      short_effect
      language {
        iso639
      }
    }
    abilityflavortexts(where: {language: {iso639: {_eq: $lang}}}, order_by: {version_group_id: desc}, limit: $textLimit) {
      flavor_text
      versiongroup {
        id
        name
