query Original151Intimidate($maxId: Int!, $abilityName: String!, $isDefault: Boolean!, $limit: Int!, $offset: Int!) {
  pokemonspecies(
    where: {
      id: {_lte: $maxId}
      pokemons: {
        is_default: {_eq: $isDefault}
        pokemonabilities: {ability: {name: {_eq: $abilityName}}}
      }
    }
    order_by: {id: asc}
    limit: $limit
    offset: $offset
  ) {
    id
    name
    pokemons(where: {is_default: {_eq: $isDefault}}, limit: 1) {
      id
      name
      pokemonabilities(where: {ability: {name: {_eq: $abilityName}}}, limit: 3) {
        ability { id name }
        is_hidden
        slot
      }
    }
  }
}

